#!/bin/bash
# Uninstall script for IntelliJ IDEA Community Edition
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling IntelliJ IDEA Community Edition..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping IntelliJ IDEA Community Edition if running..."
pkill -f "IntelliJ IDEA Community Edition" 2>/dev/null || true

# Remove /Applications/IntelliJ IDEA CE.app
echo "Removing /Applications/IntelliJ IDEA CE.app..."
if [ -d "/Applications/IntelliJ IDEA CE.app" ]; then
    rm -rf "/Applications/IntelliJ IDEA CE.app" 2>/dev/null || true
elif [ -f "/Applications/IntelliJ IDEA CE.app" ]; then
    rm -f "/Applications/IntelliJ IDEA CE.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/JetBrains/IdeaIC2025.2
echo "Removing $HOME/Library/Application Support/JetBrains/IdeaIC2025.2..."
if [ -d "$HOME/Library/Application Support/JetBrains/IdeaIC2025.2" ]; then
    rm -rf "$HOME/Library/Application Support/JetBrains/IdeaIC2025.2" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/JetBrains/IdeaIC2025.2" ]; then
    rm -f "$HOME/Library/Application Support/JetBrains/IdeaIC2025.2" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/JetBrains/IdeaIC2025.2
echo "Removing $HOME/Library/Caches/JetBrains/IdeaIC2025.2..."
if [ -d "$HOME/Library/Caches/JetBrains/IdeaIC2025.2" ]; then
    rm -rf "$HOME/Library/Caches/JetBrains/IdeaIC2025.2" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/JetBrains/IdeaIC2025.2" ]; then
    rm -f "$HOME/Library/Caches/JetBrains/IdeaIC2025.2" 2>/dev/null || true
fi

# Remove $HOME/Library/Logs/JetBrains/IdeaIC2025.2
echo "Removing $HOME/Library/Logs/JetBrains/IdeaIC2025.2..."
if [ -d "$HOME/Library/Logs/JetBrains/IdeaIC2025.2" ]; then
    rm -rf "$HOME/Library/Logs/JetBrains/IdeaIC2025.2" 2>/dev/null || true
elif [ -f "$HOME/Library/Logs/JetBrains/IdeaIC2025.2" ]; then
    rm -f "$HOME/Library/Logs/JetBrains/IdeaIC2025.2" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.jetbrains.intellij.ce.plist
echo "Removing $HOME/Library/Preferences/com.jetbrains.intellij.ce.plist..."
if [ -d "$HOME/Library/Preferences/com.jetbrains.intellij.ce.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.jetbrains.intellij.ce.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.jetbrains.intellij.ce.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.jetbrains.intellij.ce.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/com.jetbrains.intellij.ce.savedState
echo "Removing $HOME/Library/Saved Application State/com.jetbrains.intellij.ce.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.jetbrains.intellij.ce.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/com.jetbrains.intellij.ce.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/com.jetbrains.intellij.ce.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/com.jetbrains.intellij.ce.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
